'use strict';

function cloneAndValidateDay(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError('day must be an object');
  }
  const { year, month, day } = value;
  if (![year, month, day].every(Number.isInteger)) {
    throw new TypeError('day fields must be integers');
  }
  if (year < 1 || month < 1 || month > 12) {
    throw new RangeError('day is out of range');
  }
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const lengths = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > lengths[month - 1]) {
    throw new RangeError('day is out of range');
  }
  return { year, month, day };
}

function makeDayChosenEvent(day) {
  return { type: 'DAY_CHOSEN', payload: cloneAndValidateDay(day) };
}

function weekday(day) {
  const d = cloneAndValidateDay(day);
  let y = d.year;
  let m = d.month;
  if (m < 3) {
    y -= 1;
    m += 12;
  }
  return (d.day + Math.floor((13 * (m + 1)) / 5) + y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400)) % 7;
}

function createDaySelectionModel(initialDay, dispatch, navigate) {
  if (typeof dispatch !== 'function' || typeof navigate !== 'function') {
    throw new TypeError('dispatch and navigate must be functions');
  }
  let selected = initialDay === null ? null : cloneAndValidateDay(initialDay);
  return {
    select(day) {
      selected = cloneAndValidateDay(day);
      dispatch(makeDayChosenEvent(selected));
      navigate('/overview');
      return { ...selected };
    },
    getSelected() {
      return selected === null ? null : { ...selected };
    },
    isWeekend(day) {
      const value = weekday(day);
      return value === 1;
    }
  };
}

module.exports = { createDaySelectionModel, makeDayChosenEvent };

