'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['createDaySelectionModel', 'makeDayChosenEvent']);
const { createDaySelectionModel, makeDayChosenEvent } = api;

const original = { year: 2024, month: 2, day: 29 };
const event = makeDayChosenEvent(original);
assert.deepEqual(event, { type: 'DAY_CHOSEN', payload: original });
assert.notStrictEqual(event.payload, original);
event.payload.day = 1;
assert.equal(original.day, 29);

assert.throws(() => makeDayChosenEvent(null), TypeError);
assert.throws(() => makeDayChosenEvent([]), TypeError);
assert.throws(() => makeDayChosenEvent({ year: 2024, month: 2 }), TypeError);
assert.throws(() => makeDayChosenEvent({ year: 2024.5, month: 2, day: 1 }), TypeError);
assert.throws(() => makeDayChosenEvent({ year: 0, month: 1, day: 1 }), RangeError);
assert.throws(() => makeDayChosenEvent({ year: 2023, month: 2, day: 29 }), RangeError);
assert.throws(() => makeDayChosenEvent({ year: 2024, month: 13, day: 1 }), RangeError);
assert.throws(() => makeDayChosenEvent({ year: 2024, month: 4, day: 31 }), RangeError);

assert.throws(() => createDaySelectionModel(null, null, () => {}), TypeError);
assert.throws(() => createDaySelectionModel(null, () => {}, 'navigate'), TypeError);
assert.throws(() => createDaySelectionModel({ year: 2023, month: 2, day: 29 }, () => {}, () => {}), RangeError);

const calls = [];
let dispatched;
const initial = { year: 2025, month: 1, day: 6 };
const model = createDaySelectionModel(initial, value => {
  calls.push('dispatch');
  dispatched = value;
}, path => calls.push(['navigate', path]));
initial.day = 7;
assert.deepEqual(model.getSelected(), { year: 2025, month: 1, day: 6 });
const firstSnapshot = model.getSelected();
firstSnapshot.day = 20;
assert.deepEqual(model.getSelected(), { year: 2025, month: 1, day: 6 });

const selectedInput = { year: 2025, month: 7, day: 12 };
const selectedResult = model.select(selectedInput);
assert.deepEqual(calls, ['dispatch', ['navigate', '/overview']]);
assert.deepEqual(dispatched, {
  type: 'DAY_CHOSEN',
  payload: { year: 2025, month: 7, day: 12 }
});
assert.notStrictEqual(dispatched.payload, selectedInput);
assert.notStrictEqual(selectedResult, selectedInput);
selectedInput.day = 13;
selectedResult.day = 14;
dispatched.payload.day = 15;
assert.deepEqual(model.getSelected(), { year: 2025, month: 7, day: 12 });

assert.equal(model.isWeekend({ year: 2025, month: 7, day: 12 }), true);
assert.equal(model.isWeekend({ year: 2025, month: 7, day: 13 }), true);
assert.equal(model.isWeekend({ year: 2025, month: 7, day: 14 }), false);
assert.throws(() => model.isWeekend({ year: 2025, month: 2, day: 29 }), RangeError);

let navigations = 0;
const failing = createDaySelectionModel(null, () => {
  throw new Error('dispatch failed');
}, () => {
  navigations += 1;
});
assert.equal(failing.getSelected(), null);
assert.throws(() => failing.select({ year: 2026, month: 8, day: 28 }), /dispatch failed/);
assert.equal(navigations, 0);
assert.deepEqual(failing.getSelected(), { year: 2026, month: 8, day: 28 });

